import sys
from collections import deque

def countVertex(N, edges):
    if N == 1:
        return 1
    adj = [[] for _ in range(N+1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    parent = [0]*(N+1)
    depth = [0]*(N+1)
    q = deque([1])
    parent[1] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if parent[v] == 0 and v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    leaves = []
    for i in range(1, N+1):
        if len(adj[i]) == 1 and i != 1:
            leaves.append(i)

    res = 0
    while leaves:
        res += 1
        new_leaves = []
        for leaf in leaves:
            u = parent[leaf]
            adj[u].remove(leaf)
            if len(adj[u]) == 1 and u != 1:
                new_leaves.append(u)
        leaves = new_leaves
    return res
